 text.push_str("\n[Protocol](artifacts/design.md), [all counts](artifacts/analysis.json), [metrics](artifacts/metrics.json), [source audit](artifacts/source-audit.json), [native build](artifacts/native/result.json), [proof inventory](artifacts/proof-inventory.json), [closing pins](artifacts/pins.json).\n");
 let mut paths=vec![];walk(r,&mut paths);paths.sort();for from in paths{let rel=from.strip_prefix(r).unwrap();let ext=from.extension().and_then(|x|x.to_str()).unwrap_or("");if !rel.starts_with("source")&&! ["rs","md","json","jsonl","log","txt","proof","public"].contains(&ext){continue}let to=d.join("artifacts").join(rel);fs::create_dir_all(to.parent().unwrap()).unwrap();fs::copy(&from,&to).unwrap();assert_eq!(hash(from),hash(to));}
