 let manifest=read("/home/ubuntu/src/zk-tools/zopro/docs/benchmarks/2026-10-28-g2-borrowed-adoption/artifacts/production-source-manifest.json");let mut source=BTreeMap::new();for f in manifest["source_files_sha256"].as_object().unwrap().keys(){let from=r.join("source").join(f);let to=d.join("artifacts/source").join(f);assert_eq!(hash(&from),hash(to));source.insert(f.clone(),hash(from));}let f="crates/zopro-core/src/msm/reduction_census.rs";assert_eq!(hash(r.join("source").join(f)),hash(d.join("artifacts/source").join(f)));source.insert(f.into(),hash(r.join("source").join(f)));assert_eq!(source.len(),175);save(d.join("artifacts/complete-source-pins.json"),&json!(source));seal();
